<script setup lang="ts">const shop=useShop();const form=reactive({name:'',email:'',password:'',confirm:''});function submit(){if(form.name.trim().length<2||!/^\S+@\S+\.\S+$/.test(form.email)||form.password.length<4||form.password!==form.confirm){shop.notify('Check your name, email, and matching demo passwords.','error');return}shop.user={name:form.name.trim(),email:form.email};shop.saveUser();shop.notify('Demo profile created. Password was not saved.');navigateTo('/account')}</script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-14"><div class="mx-auto max-w-md"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Join the VY edit</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Create account<span class="text-brand">.</span></h1><p class="mt-3 text-sm text-gray-500">Frontend demo only. Your password is not saved or securely authenticated.</p><form class="mt-7 space-y-4" @submit.prevent="submit"><label class="block text-xs font-semibold">Full name<input v-model="form.name" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label><label class="block text-xs font-semibold">Email<input v-model="form.email" type="email" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label><label class="block text-xs font-semibold">Demo password<input v-model="form.password" type="password" minlength="4" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label><label class="block text-xs font-semibold">Confirm demo password<input v-model="form.confirm" type="password" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label><button class="w-full rounded-full bg-ink px-6 py-4 text-xs font-bold uppercase tracking-wider text-white hover:bg-brand">Create demo profile</button></form><p class="mt-5 text-center text-sm text-gray-500">Already have a demo profile? <NuxtLink to="/login" class="font-semibold text-brand">Log in</NuxtLink></p></div></div></template>
